let imageZoom=1,imageFitWidth=0,viewerFitMode='height';
function applyImageZoom(next,anchor){const stage=$('#zoom-stage'),canvas=$('#image-canvas'),oldWidth=canvas.getBoundingClientRect().width||stage.clientWidth,oldLeft=Math.max(0,(stage.clientWidth-oldWidth)/2);const x=anchor?.x??stage.clientWidth/2,y=anchor?.y??stage.clientHeight/2;const pointX=(stage.scrollLeft+x-oldLeft)/oldWidth;const oldTop=parseFloat(getComputedStyle(canvas).marginTop)||0,pointY=(stage.scrollTop+y-oldTop)/oldWidth;imageZoom=Math.max(.1,Math.min(8,next));const width=(imageFitWidth||stage.clientWidth)*imageZoom;canvas.style.width=width+'px';for(let i=0;i<2;i++)canvas.style.marginTop=Math.max(0,(stage.clientHeight-canvas.getBoundingClientRect().height)/2)+'px';const newTop=parseFloat(canvas.style.marginTop)||0,newLeft=Math.max(0,(stage.clientWidth-width)/2);stage.scrollLeft=pointX*width+newLeft-x;stage.scrollTop=pointY*width+newTop-y;$('#zoom-level').textContent=Math.round(imageZoom*100)+'%';}
function fitImageViewer(scale=1,mode=viewerFitMode){const image=$('#large-image'),stage=$('#zoom-stage');if(!image.naturalWidth||!image.naturalHeight)return;viewerFitMode=mode;for(let i=0;i<2;i++){imageFitWidth=mode==='width'?stage.clientWidth:stage.clientHeight*image.naturalWidth/image.naturalHeight;$('#image-canvas').style.width=imageFitWidth*scale+'px'}applyImageZoom(scale);stage.scrollTo(Math.max(0,(imageFitWidth*imageZoom-stage.clientWidth)/2),mode==='width'?Math.max(0,($('#image-canvas').getBoundingClientRect().height-stage.clientHeight)/2):0)}
async function openImageViewer(src){const image=$('#large-image');image.style.visibility='hidden';image.src=src;if(!$('#image-viewer').open)$('#image-viewer').showModal();try{await image.decode();if($('#image-viewer').open&&image.src===src){fitImageViewer(1,'height');image.style.visibility='visible'}}catch{image.style.visibility='visible';toast('無法開啟圖片')}}

$('#zoom-stage').addEventListener('wheel',e=>{e.preventDefault();const rect=$('#zoom-stage').getBoundingClientRect();const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?rect.height:1);applyImageZoom(imageZoom*Math.exp(-delta*.0015),{x:e.clientX-rect.left,y:e.clientY-rect.top})},{passive:false});
$('#zoom-in').onclick=()=>applyImageZoom(imageZoom*1.2);$('#zoom-out').onclick=()=>applyImageZoom(imageZoom/1.2);$('#zoom-fit').onclick=()=>fitImageViewer(1,'width');window.addEventListener('resize',()=>{if($('#image-viewer').open)fitImageViewer(imageZoom)});
const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function panCamera(){
 const scene=$('#scene'),character=$('#character'),path=$('#path'),background=$('.background-layer');
 const distance=(state.position-cameraStart)*scene.clientWidth*.94/8;
 character.classList.remove('walking');scene.classList.add('camera-panning');
 const timing={duration:950,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'};
 const animations=[$('#portal-layer').animate([{transform:'translateX(0)'},{transform:`translateX(-${distance}px)`}],timing),path.animate([{transform:'translateX(0)'},{transform:`translateX(-${distance}px)`}],timing),character.animate([{transform:'translateX(-50%)'},{transform:`translateX(calc(-50% - ${distance}px))`}],timing),background.animate([{backgroundPosition:`calc(50% + ${sceneryOffset}px) 50%`},{backgroundPosition:`calc(50% + ${sceneryOffset-distance*.22}px) 50%`}],timing)];
 try{await Promise.all(animations.map(a=>a.finished));cameraStart=state.position;sceneryOffset-=distance*.22;background.style.backgroundPosition=`calc(50% + ${sceneryOffset}px) 50%`;character.style.transition='none';renderGame();animations.forEach(a=>a.cancel());void character.offsetWidth;character.style.transition=''}finally{animations.forEach(a=>a.cancel());scene.classList.remove('camera-panning');character.classList.add('walking')}
}
