async function finishChallenge(answer){if(!current)return;const questionId=current.id,previousXp=state.xp,result=questionType(current)==='image'?completeQuestion(state,questionId):completeAutomaticQuestion(state,questionId,answer);if(!result)return;current=null;state.pendingChallengeId=null;const find=mineGem(state);enqueueLevelRewards(state,previousXp);state.answerNotice={stars:state.lastAnswerReward,xp:state.lastAnswerReward,portalReady:result.portalReady};dialogueUI.say(result.portalReady?'portalReady':'correct',{stars:state.lastAnswerReward});state.pendingGemFind=find?{id:find.gem.id,quantity:find.quantity,isNew:find.isNew}:null;renderGame();await save();$('#challenge').close();$('#scene-roll').disabled=false;await resumeRewards()}
