function openEvent(type){const options=state.events[type].length?state.events[type]:[{title:'平靜的一刻',description:'目前沒有設定此類事件，繼續前進吧。',xp:0}];pendingEvent=options[Math.floor(Math.random()*options.length)];$('#event-kind').textContent=type==='chance'?'CHANCE · 機會':'FATE · 命運';$('#event-symbol').textContent=type==='chance'?'✦':'☽';$('#event-title').textContent=pendingEvent.title;$('#event-description').textContent=pendingEvent.description;$('#event-reward').textContent=pendingEvent.xp>0?'＋'+pendingEvent.xp+' EXP / '+pendingEvent.xp+' ★':pendingEvent.xp<0?pendingEvent.xp+' EXP':'不影響經驗與星星';dialogueUI.say(type);$('#event-dialog').dataset.kind=type;$('#event-dialog').showModal()}
$('#event-dialog').addEventListener('cancel',e=>e.preventDefault());$('#event-confirm').onclick=async()=>{if(!pendingEvent)return;const previousXp=state.xp;grantReward(state,pendingEvent.xp);enqueueLevelRewards(state,previousXp);pendingEvent=null;renderGame();save();$('#event-dialog').close();toast('事件已完成，繼續前進吧！');await resumeRewards()};
function populateSettings(){$('#theme-mode').value=normalizeThemeMode(state.themeMode);dialogueUI.populateSettings();settingsDirty=false;settingsRevision=0;$('#settings-unsaved-status').textContent='修改後請儲存設定';$('#dice-scale').value=Math.round(normalizeDiceScale(state.diceScale)*100);$('#auto-expand-images').checked=state.autoExpandImages!==false;$('#repeat-questions').checked=state.repeatQuestions;updateAnsweredCount();dollUI.populateDropSettings();$('#font-scale').value=Math.round(state.fontScale*100);$('#font-scale-label').textContent=Math.round(state.fontScale*100)+'%';$('#player-scale').value=Math.round(state.playerScale*100);$('#player-scale-label').textContent=Math.round(state.playerScale*100)+'%';sceneUI.renderSettings();renderAdventureAppearancePreview();updateSizePreviews();$('#settings-stars-count').textContent=state.stars+' ★';$('#player-name-input').value=state.playerName;$('#scene-target').value=state.sceneTarget;const range=answerRewardRange(state);$('#reward-min').value=range.min;$('#reward-max').value=range.max;const typeList=$('#enabled-question-types');typeList.replaceChildren();for(const t of questionTypes){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.value=t;input.checked=enabledQuestionTypes(state).includes(t);label.append(input,document.createTextNode(({image:'圖片題',choice:'選擇題','true-false':'是非題'})[t]));typeList.append(label)}const list=$('#enabled-folders');list.replaceChildren();['',...state.folders].forEach(f=>{let label=document.createElement('label');let input=document.createElement('input');input.type='checkbox';input.value=f;input.checked=!state.disabledFolders.includes(f);label.append(input,document.createTextNode((f||'未分類')+'（'+state.questions.filter(q=>(q.folder||'')===f).length+' 題）'));list.append(label)});}
$('#settings-form').onsubmit=async e=>{e.preventDefault();const playerName=$('#player-name-input').value.trim();if(!playerName){toast('請輸入玩家名稱');return}const target=Number($('#scene-target').value),rewardMin=Number($('#reward-min').value),rewardMax=Number($('#reward-max').value);if(!Number.isInteger(target)||target<1||target>1000)return;if(!Number.isInteger(rewardMin)||!Number.isInteger(rewardMax)||rewardMin<0||rewardMax>10000||rewardMin>rewardMax){toast('獎勵需為 0–10000 的整數，Min 不可大於 Max');return}const drawWeights=dollUI.readDropSettings(),sceneSettings=sceneUI.readSettings();if(!drawWeights||!sceneSettings)return;const revision=settingsRevision;state.dialogue=dialogueUI.readSettings();state.repeatQuestions=$('#repeat-questions').checked;state.autoExpandImages=$('#auto-expand-images').checked;state.sceneConfigs=sceneSettings;state.doll.drawCategoryWeights=Object.fromEntries(drawWeights);state.diceScale=normalizeDiceScale(Number($('#dice-scale').value)/100);state.fontScale=normalizeFontScale(Number($('#font-scale').value)/100);state.playerScale=normalizePlayerScale(Number($('#player-scale').value)/100);state.playerName=playerName.slice(0,20);state.sceneTarget=target;state.rewardMin=rewardMin;state.rewardMax=rewardMax;state.themeMode=normalizeThemeMode($('#theme-mode').value);state.enabledQuestionTypes=$$('#enabled-question-types input:checked').map(i=>i.value);state.disabledFolders=$$('#enabled-folders input').filter(i=>!i.checked).map(i=>i.value);dialogueUI.refresh();renderGame();renderAdventureAppearancePreview();if(await save()){if(revision===settingsRevision){settingsDirty=false;$('#settings-unsaved-status').textContent='設定已儲存'}toast(readyPortal(state)?'設定已儲存，擲骰前往魔法陣！':'冒險設定已儲存')}};
