function renderLibrary(){updateAnsweredCount();const folders=$('#folders');folders.replaceChildren();['全部','未分類',...state.folders].forEach(f=>{let btn=document.createElement('button');btn.className='folder'+(folder===f?' active':'');let count=f==='全部'?state.questions.length:state.questions.filter(q=>(q.folder||'未分類')===f).length;btn.textContent=(f==='全部'?'▧ ':'▱ ')+f;let badge=document.createElement('span');badge.textContent=count;btn.append(badge);btn.onclick=()=>{folder=f==='未分類'?'':f;selected.clear();renderLibrary()};if(f==='未分類'&&folder==='')btn.classList.add('active');folders.append(btn)});$('#folder-title').textContent=folder==='全部'?'所有挑戰':folder||'未分類';let qs=visibleQuestions();$('#question-count').textContent=qs.length+' 個挑戰';const grid=$('#question-grid');grid.replaceChildren();qs.forEach(q=>{let card=document.createElement('article');card.className='question-card';let cb=document.createElement('input');cb.type='checkbox';cb.checked=selected.has(q.id);cb.setAttribute('aria-label','選取 '+q.title);cb.onchange=()=>{cb.checked?selected.add(q.id):selected.delete(q.id);updateBatch()};card.append(cb);let art=document.createElement(q.image?'img':'div');art.className='question-image'+(q.image?'':' demo');if(q.image){art.src=q.image;art.alt=q.title;art.loading='lazy';art.decoding='async'}else art.textContent=q.emoji||'✧';card.append(art);let body=document.createElement('div');body.className='question-card-content';let tag=document.createElement('small');tag.textContent=q.folder||'未分類';let title=document.createElement('h3');title.textContent=q.title;let edit=document.createElement('button');edit.textContent='編輯挑戰 ↗';edit.onclick=()=>editQuestion(q);body.append(tag,title,edit);card.append(body);grid.append(card)});$('#empty').classList.toggle('hidden',qs.length>0);optionList($('#move-folder'));updateBatch();}
function updateBatch(){$('#batch').classList.toggle('hidden',selected.size===0);$('#selected-count').textContent=`已選取 ${selected.size} 個挑戰`;let qs=visibleQuestions();$('#select-all').checked=qs.length>0&&qs.every(q=>selected.has(q.id));$('#select-all').indeterminate=qs.some(q=>selected.has(q.id))&&!$('#select-all').checked}
$('#search').oninput=()=>{selected.clear();renderLibrary()};$('#select-all').onchange=e=>{visibleQuestions().forEach(q=>e.target.checked?selected.add(q.id):selected.delete(q.id));renderLibrary()};$('#batch-move').onclick=()=>{let f=$('#move-folder').value;state.questions.forEach(q=>{if(selected.has(q.id))q.folder=f});selected.clear();save();renderLibrary();toast('挑戰已移至 '+(f||'未分類'))};$('#batch-delete').onclick=()=>{if(!confirm(`確定刪除選取的 ${selected.size} 個挑戰？此動作無法復原。`))return;state.questions=state.questions.filter(q=>!selected.has(q.id));selected.clear();save();renderLibrary();toast('挑戰已刪除')};$('#new-folder').onclick=()=>{const value=prompt('為新的題庫資料夾取個名字：');if(value===null)return;try{const name=folderName(state,value);state.folders.push(name);folder=name;selected.clear();save();renderLibrary()}catch(error){toast(error.message)}};
function renderFolderManager(focusName,focusAction){
 const list=$('#folder-manager-list');list.replaceChildren();
 if(!state.folders.length){const empty=document.createElement('p');empty.textContent='尚無自訂資料夾，可在題庫左側新增。';list.append(empty)}
 state.folders.forEach((name,index)=>{
  const row=document.createElement('form');row.className='folder-manager-row';row.dataset.folder=name;
  const label=document.createElement('label'),input=document.createElement('input');label.textContent='資料夾名稱';input.value=name;input.maxLength=40;input.required=true;input.setAttribute('aria-label','資料夾名稱：'+name);label.append(input);
  const info=document.createElement('small');info.textContent=state.questions.filter(q=>q.folder===name).length+' 題';
  const actions=document.createElement('div');actions.className='folder-manager-actions';
  const makeButton=(action,title)=>{const button=document.createElement('button');button.className='secondary';button.type='button';button.dataset.folderAction=action;button.textContent=title;return button};
  const rename=makeButton('rename','儲存名稱');rename.type='submit';
  row.onsubmit=e=>{e.preventDefault();try{const next=renameFolder(state,name,input.value);if(folder===name)folder=next;renderLibrary();renderFolderManager(next,'rename');save();toast('資料夾名稱已更新')}catch(error){toast(error.message);input.focus()}};
  const up=makeButton('up','↑'),down=makeButton('down','↓');up.setAttribute('aria-label','上移 '+name);down.setAttribute('aria-label','下移 '+name);up.disabled=index===0;down.disabled=index===state.folders.length-1;
  for(const [button,delta] of [[up,-1],[down,1]])button.onclick=()=>{if(moveFolder(state,name,delta)){renderLibrary();renderFolderManager(name,delta<0?'up':'down');save();toast('資料夾順序已儲存')}};
  const remove=makeButton('delete','刪除');remove.setAttribute('aria-label','刪除資料夾 '+name);remove.onclick=()=>{const count=state.questions.filter(q=>q.folder===name).length;if(!confirm(`確定刪除「${name}」資料夾？其中 ${count} 題及圖檔會保留並移至「未分類」。`))return;removeFolder(state,name);if(folder===name)folder='';renderLibrary();renderFolderManager();save();toast('資料夾已刪除，題目與圖檔已保留於未分類')};
  actions.append(rename,up,down,remove);row.append(label,info,actions);list.append(row);
 });
 if(focusName){const row=[...list.children].find(el=>el.dataset.folder===focusName);row?.querySelector(`[data-folder-action="${focusAction}"]:not(:disabled)`)?.focus({preventScroll:true})}
}
$('#manage-folders').onclick=()=>{renderFolderManager();$('#folder-manager').showModal()};

function editQuestion(q){editing=q.id;$('#edit-title').value=q.title;$('#edit-prompt').value=q.prompt;$('#edit-answer').value=q.answer;$('#edit-choice-options').hidden=questionType(q)!=='choice';for(const k of 'ABCD')$('#edit-option-'+k).value=q.options?.[k]||'';$('#edit-answer-label').textContent=questionType(q)==='choice'?'正確答案（A～D）':questionType(q)==='true-false'?'正確答案（TRUE/FALSE）':'參考答案';optionList($('#edit-folder'));$('#edit-folder').value=q.folder;$('#editor').showModal()}
$('#edit-form').onsubmit=e=>{e.preventDefault();let q=state.questions.find(q=>q.id===editing);if(q){if(questionType(q)!=='image'){const next={...q,prompt:$('#edit-prompt').value.trim(),answer:$('#edit-answer').value.trim().toUpperCase()};if(questionType(q)==='choice')next.options=Object.fromEntries([...'ABCD'].map(k=>[k,$('#edit-option-'+k).value.trim()]));try{validateTypedQuestion(next)}catch(error){toast(error.message);return}Object.assign(q,next)}q.title=$('#edit-title').value.trim()||'未命名挑戰';q.prompt=$('#edit-prompt').value.trim();q.answer=questionType(q)==='image'?$('#edit-answer').value.trim():$('#edit-answer').value.trim().toUpperCase();q.folder=$('#edit-folder').value;save();renderLibrary();toast('挑戰已儲存')}$('#editor').close()};$('#upload').onclick=()=>$('#files').click();
async function readImage(file,maxDimension=1600,quality=.88){if(!isImageFile(file))throw Error('請選擇圖片檔案');if(file.size>20*1024*1024)throw Error('圖片超過 20 MB');const webp=isWebPFile(file),source=await (webp?readWebPData(file):readImageData(file));return new Promise((resolve,reject)=>{const img=new Image();img.onerror=()=>reject(Error('無法辨識圖片格式'));img.onload=()=>{try{const ratio=Math.min(1,maxDimension/Math.max(img.naturalWidth,img.naturalHeight));if(webp&&ratio===1){resolve(source);return}const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(img.naturalHeight*ratio));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/webp',quality))}catch{reject(Error('無法處理此圖片，請改用 WebP、PNG 或 JPEG'))}};img.src=source})}

$('#files').onchange=async e=>{let files=[...e.target.files];$('#upload').disabled=true;let count=0;for(let file of files){try{if(!isImageFile(file))throw Error('請選擇圖片檔案');let image=await readImage(file);state.questions.push({id:crypto.randomUUID(),title:file.name.replace(/\.[^.]+$/,''),prompt:'',answer:'',image,folder:folder==='全部'?'':folder});count++}catch(err){toast(file.name+'：'+err.message)}}await save();$('#upload').disabled=false;e.target.value='';renderLibrary();if(count)toast(`已新增 ${count} 個圖片挑戰，可點擊編輯補上題目與答案。`)};
