async function init(){try{await dbReady;let saved=await new Promise((resolve,reject)=>{let r=db.transaction('data').objectStore('data').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});const response=await fetch(new URL('../default-state.json?v='+publishedPresetVersion,assetUrl('forest.webp')),{cache:'no-store'});if(!response.ok)throw Error('預設設定載入失敗');const defaults=await response.json();const resolveMedia=value=>{if(typeof value==='string'&&(isBundledMedia(value)||isBundledMedia(value,'audio')))return new URL('../'+value,assetUrl('forest.webp')).href;if(Array.isArray(value))return value.map(resolveMedia);if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([key,v])=>[key,resolveMedia(v)]));return value};latestDefaults=resolveMedia(defaults);if(!saved)saved=structuredClone(latestDefaults);if(saved&&Array.isArray(saved.questions)&&Array.isArray(saved.folders)){state={...structuredClone(latestDefaults),...Object.fromEntries([...Object.keys(latestDefaults),'builtInImages','enabledQuestionTypes'].filter(key=>Object.hasOwn(saved,key)).map(key=>[key,saved[key]]))};state.dialogue=normalizeDialogueSettings(state.dialogue);state.position=Math.max(0,Math.floor(Number(state.position)||0));state.xp=Math.max(0,Number(state.xp)||0);state.sceneIndex=Math.max(0,Math.floor(Number(state.sceneIndex)||0));state.sceneAnswers=Math.max(0,Math.floor(Number(state.sceneAnswers)||0));state.sceneTarget=Number.isInteger(state.sceneTarget)&&state.sceneTarget>=1&&state.sceneTarget<=1000?state.sceneTarget:5;const rewardRange=answerRewardRange(state);state.rewardMin=rewardRange.min;state.rewardMax=rewardRange.max;state.stars=Number.isFinite(state.stars)&&state.stars>=0?Math.floor(state.stars):Math.floor(state.xp);state.disabledFolders=Array.isArray(state.disabledFolders)?state.disabledFolders:[];state.autoExpandImages=state.autoExpandImages!==false;state.events=normalizeEvents(state.events);state.repeatQuestions=state.repeatQuestions!==false;state.answeredQuestionIds=Array.isArray(state.answeredQuestionIds)?[...new Set(state.answeredQuestionIds)].filter(id=>state.questions.some(q=>q.id===id)):[];state.diceScale=normalizeDiceScale(state.diceScale);state.playerScale=normalizePlayerScale(state.playerScale);state.fontScale=normalizeFontScale(state.fontScale);state.themeMode=normalizeThemeMode(state.themeMode);state.avatar=typeof state.avatar==='string'?state.avatar:'';state.playerName=typeof state.playerName==='string'&&state.playerName.trim()?state.playerName.trim().slice(0,20):'森林旅人';state.doll=normalizePaperDoll(state.doll);state.gems=normalizeGems(state.gems);state.sceneConfigs=normalizeSceneConfigs(state.sceneConfigs);}}catch(error){$('#boot-error').classList.remove('hidden');$('#startup-screen').textContent='載入尚未完成，請重新載入頁面。';return}cameraStart=windowStart(state.position);renderGame();renderLibrary();try{await waitForAdventureAssets();}catch(error){$('#boot-error').classList.remove('hidden');$('#startup-screen').textContent='素材載入失敗，請重新載入頁面。';return}$('#scene-roll').disabled=false;document.body.dataset.ready='true';clearLegacyStorage();showSceneIntro();$('#boot-error').classList.add('hidden');dialogueUI.say('start');await resumeRewards();const pending=getPendingChallenge(state);if(pending&&!document.querySelector('dialog[open]'))openChallenge(pending)}
async function finishDollPortal(){if(state.doll.pendingReward?.kind==='level'){if(finishLevelReward(state)){renderGame();await save()}return}const pending=state.doll.pendingReward;if(!pending||pending.selected===null||pending.sceneIndex!==state.sceneIndex)return;$('#scene').classList.add('portal-transition');await delay(650);if(!enterPortal(state)){toast('尚未達到場景門檻');$('#scene').classList.remove('portal-transition');return}state.doll.pendingReward=null;portalDestination=null;cameraStart=0;sceneryOffset=0;$('.background-layer').style.backgroundPosition='50% 50%';$('#character').style.transition='none';renderGame();void $('#character').offsetWidth;$('#character').style.transition='';await save();await delay(300);$('#scene').classList.remove('portal-transition');dialogueUI.say('newScene');toast('配件獎勵已收下，進入'+currentScene(state).name)}
let appearancePreviewDoc=null,appearancePreviewJob=0,appearancePreviewGeneration=0,appearancePreviewStylesReady=false;
function renderAdventureAppearancePreview(){
 const frame=$('#appearance-preview-frame'),generation=++appearancePreviewGeneration;frame.width=window.innerWidth;frame.height=window.innerHeight;frame.style.width=window.innerWidth+'px';frame.style.height=window.innerHeight+'px';appearancePreviewDoc=null;appearancePreviewStylesReady=false;frame.removeAttribute('data-ready');$('#appearance-preview-viewport').dataset.previewReady='false';
 frame.onload=async()=>{if(generation!==appearancePreviewGeneration)return;const doc=frame.contentDocument;if(!doc||doc.location.href!=='about:srcdoc'||doc.compatMode!=='CSS1Compat')return;appearancePreviewDoc=doc;
  const style=doc.createElement('style');style.textContent='html,body{margin:0!important;padding:0!important;overflow:hidden!important;scrollbar-gutter:auto!important}body>main{margin:0!important;padding:0!important;max-width:none!important;display:flow-root!important}*,*:before,*:after{animation:none!important;transition:none!important}';doc.head.append(style);
  const main=doc.createElement('main'),clone=doc.importNode($('#adventure'),true);clone.classList.remove('hidden');clone.querySelector('#scene').classList.remove('intro-active','camera-panning','portal-transition','background-loading');clone.querySelector('#scene-loading-hint')?.remove();const background=state.sceneConfigs[state.sceneIndex%5].background;clone.querySelector('#scene').dataset.customBackground=background?'true':'false';clone.querySelector('.background-layer').style.backgroundImage=`url("${background||state.builtInImages?.forest||assetUrl('forest.webp')}")`;clone.querySelector('#character').classList.remove('walking');clone.querySelector('#movement-status').classList.add('hidden');clone.querySelector('.scene-title').setAttribute('aria-hidden','true');main.inert=true;main.append(clone);doc.body.append(main);
  for(const image of doc.images)image.addEventListener('load',scheduleAppearancePreview,{once:true});
  const loaded=await Promise.all($$('link[rel=stylesheet]').map(sheet=>new Promise(resolve=>{const link=doc.createElement('link');link.rel='stylesheet';link.href=sheet.href;link.onload=()=>resolve(true);link.onerror=()=>resolve(false);doc.head.insertBefore(link,style)})));
  if(generation!==appearancePreviewGeneration)return;if(loaded.some(ok=>!ok)){toast('預覽樣式載入失敗，請重新整理頁面');return}
  void main.offsetHeight;await doc.fonts.ready;if(generation!==appearancePreviewGeneration)return;appearancePreviewStylesReady=true;scheduleAppearancePreview();
 };
 frame.srcdoc='<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body data-appearance="obsidian"></body></html>';
}
function scheduleAppearancePreview(){cancelAnimationFrame(appearancePreviewJob);appearancePreviewJob=requestAnimationFrame(updateAdventureAppearancePreview)}
function updateAdventureAppearancePreview(){
 const doc=appearancePreviewDoc,viewport=$('#appearance-preview-viewport'),canvas=$('#appearance-preview-canvas'),frame=$('#appearance-preview-frame');if(!appearancePreviewStylesReady||!doc||!viewport.clientWidth||!doc.querySelector('#scene'))return;
 const main=$('main'),mainStyle=getComputedStyle(main),sourceWidth=Math.max(1,main.getBoundingClientRect().width-parseFloat(mainStyle.paddingLeft)-parseFloat(mainStyle.paddingRight)),scale=Math.min(1,viewport.clientWidth/sourceWidth);
 frame.style.width=window.innerWidth+'px';doc.querySelector('main').style.setProperty('width',sourceWidth+'px','important');
 doc.documentElement.style.setProperty('--player-scale',Number($('#player-scale').value)/100);doc.documentElement.style.setProperty('--dice-scale',Number($('#dice-scale').value)/100);doc.documentElement.style.setProperty('--font-scale',Number($('#font-scale').value)/100);doc.body.dataset.appearance=normalizeThemeMode($('#theme-mode').value);doc.documentElement.style.removeProperty('--green');doc.querySelector('#player-name').textContent=$('#player-name-input').value.trim()||state.playerName;
 layoutCharacterScene(doc);const height=Math.ceil(doc.querySelector('main').getBoundingClientRect().height);frame.style.height=Math.max(window.innerHeight,height)+'px';canvas.style.width=sourceWidth+'px';canvas.style.height=height+'px';canvas.style.transform='scale('+scale+')';viewport.style.height=Math.ceil(height*scale)+2+'px';frame.dataset.ready='true';viewport.dataset.previewReady='true';
}
function updateSizePreviews(){for(const key of ['dice','font','player'])$('#'+key+'-scale-label').textContent=$('#'+key+'-scale').value+'%';scheduleAppearancePreview()}
$('#dice-scale').oninput=$('#font-scale').oninput=$('#player-scale').oninput=updateSizePreviews;
$('#player-name-input').addEventListener('input',scheduleAppearancePreview);
new ResizeObserver(scheduleAppearancePreview).observe($('#appearance-preview-viewport'));window.addEventListener('resize',scheduleAppearancePreview);

function updateAnsweredCount(){const count=(state.answeredQuestionIds||[]).filter(id=>state.questions.some(q=>q.id===id)).length;$('#answered-count').textContent=count+' 題';$('#library-answered-count').textContent=count+' 題已作答'}
function clearAnswerHistory(){if(!confirm('清空已作答紀錄？題目與圖片會保留，清空後可再次出題。'))return;clearAnsweredQuestions(state);updateAnsweredCount();save();toast('已清空作答紀錄，題庫與獎勵進度保留')}
$('#clear-answered').onclick=$('#library-clear-answered').onclick=clearAnswerHistory;
$('#clear-stars').onclick=()=>{if(!confirm('確定將星星歸零？經驗值、等級與收藏不會改變。'))return;clearStars(state);$('#settings-stars-count').textContent='0 ★';renderGame();save();toast('星星已歸零，經驗值與等級保留')};
backupUI=createBackupUI({getState:()=>state,waitForSaves:()=>saveQueue,assetUrl,toast,replaceState:async next=>{await saveQueue;await dbReady;await new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(next,'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||Error('無法儲存還原資料'));tx.onabort=()=>reject(tx.error||Error('儲存已取消'))})}});
eventUI=createEventUI({getState:()=>state,toast,onChange:markEventSettingsChanged});
sceneUI=createSceneUI({getState:()=>state,save,renderGame,toast,assetUrl,readImage,onChange:markSettingsChanged});
gemUI=createGemUI({getState:()=>state,save,toast,readImage,assetUrl,resumeRewards,onChange:markGemSettingsChanged});
dollUI=createDollUI({getState:()=>state,save,renderGame,toast,assetUrl,navigate:showPage,finishPortal:finishDollPortal,resumeRewards});
dialogueUI=createDialogueUI({getState:()=>state,toast,onChange:markSettingsChanged,onLayout:()=>layoutCharacterScene(document)});
init();

function markEventSettingsChanged(){eventSettingsDirty=true;eventSettingsRevision++;$('#event-settings-status').textContent='尚有未儲存的變更'}
$('#event-settings-form').addEventListener('input',markEventSettingsChanged);
$('#event-settings-form').addEventListener('change',markEventSettingsChanged);
$('#event-settings-form').onsubmit=async e=>{e.preventDefault();const events=eventUI.readSettings();if(!events)return;const revision=eventSettingsRevision;state.events=events;if(await save()){if(revision===eventSettingsRevision){eventSettingsDirty=false;$('#event-settings-status').textContent='機會與命運已儲存'}toast('機會與命運已儲存')}};
function selectLibraryTab(tab){const questions=tab==='questions';for(const button of $$('[data-library-tab]')){const selected=button.dataset.libraryTab===tab;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1}$('#library-questions').classList.toggle('hidden',!questions);$('#library-events').classList.toggle('hidden',questions);$('#upload').classList.toggle('hidden',!questions);$('#csv-question-tools').classList.toggle('hidden',!questions)}
$$('[data-library-tab]').forEach(button=>{button.onclick=()=>selectLibraryTab(button.dataset.libraryTab);button.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tab=e.key==='Home'?'questions':e.key==='End'?'events':button.dataset.libraryTab==='questions'?'events':'questions';selectLibraryTab(tab);$('[data-library-tab='+tab+']').focus()}});

$$('[data-overview-page]').forEach(button=>button.onclick=()=>showPage(button.dataset.overviewPage));

$('#theme-mode').addEventListener('change',scheduleAppearancePreview);

async function waitForAdventureAssets(){const loaded=await sceneUI.whenBackgroundReady();if(!loaded)throw Error('場景載入失敗');await document.fonts.ready;const sources=new Set([...document.querySelectorAll('#adventure img')].map(img=>img.src));sources.add(state.builtInImages?.stone||assetUrl('stone.webp'));await Promise.all([...sources].map(src=>new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve();image.onerror=reject;image.src=src})));layoutCharacterScene(document)}

// Delete only retired Mosslight databases after the current app has loaded successfully.
function clearLegacyStorage(){
 let notified=false;
 for(const name of ['mosslight','mosslight-fantasy-preview','mosslight-current-preview']){
  try{const request=indexedDB.deleteDatabase(name);request.onblocked=()=>{if(!notified){notified=true;toast('請關閉其他舊版遊戲分頁，讓舊資料清理完成。')}};request.onerror=()=>{if(!notified){notified=true;toast('舊資料暫時無法清理，下次開啟時會再次嘗試。')}}}catch{}
 }
}
